import { Router } from "express";
import type { Request, Response } from "express";
import { sql } from "../lib/db.js";
import type {
  AdminDashboardRequest,
  AdminDashboardResponse,
  AdminSubscribersRequest,
  AdminSubscribersResponse,
  AdminSubscribersExportRequest,
  AdminSubscribersExportResponse,
  AdminSettingsResponse,
  AdminSaveTemplateRequest,
  AdminSaveTemplateResponse,
  AdminSaveQuietHoursRequest,
  AdminSaveQuietHoursResponse,
  DashboardItem,
  OverallMetrics,
  SubscriberItem,
  NotificationSettingsRow,
} from "../types/contracts.js";

export const adminRouter = Router();

// ─── Cursor pagination helpers ────────────────────────────────────────────────

const PAGE_SIZE = 20;

function encodeCursor(id: string): string {
  return Buffer.from(id).toString("base64url");
}

function decodeCursor(cursor: string): string {
  return Buffer.from(cursor, "base64url").toString("utf8");
}

// ─── Template rendering helper ─────────────────────────────────────────────────

function renderTemplate(template: string, vars: Record<string, string>): string {
  return template.replace(/\{\{(\w+)\}\}/g, (_match, key: string) => vars[key] ?? `{{${key}}}`);
}

// ─── GET /admin/dashboard ──────────────────────────────────────────────────────

adminRouter.get("/admin/dashboard", async (req: Request, res: Response): Promise<void> => {
  const cursorRaw = typeof req.query.cursor === "string" ? req.query.cursor : null;

  try {
    let cursorId: string | null = null;
    if (cursorRaw) {
      cursorId = decodeCursor(cursorRaw);
    }

    // Fetch dashboard snapshots ordered by active_waitlist_count DESC, id for stable cursor
    let snapshots: {
      id: string;
      product_external_id: bigint;
      variant_external_id: bigint | null;
      item_display_name: string;
      active_waitlist_count: number;
      total_signups: number;
      total_notified: number;
      total_conversions: number;
      last_restock_at: Date | null;
    }[];

    if (cursorId) {
      // Get the cursor row's count for keyset pagination
      const [cursorRow] = await sql<{ active_waitlist_count: number; id: string }[]>`
        SELECT active_waitlist_count, id FROM dashboard_snapshots WHERE id = ${cursorId}
      `;
      if (!cursorRow) {
        res.status(400).json({ error: "invalid cursor" });
        return;
      }
      snapshots = await sql<typeof snapshots>`
        SELECT id, product_external_id, variant_external_id, item_display_name,
               active_waitlist_count, total_signups, total_notified, total_conversions,
               last_restock_at
        FROM dashboard_snapshots
        WHERE (active_waitlist_count, id) < (${cursorRow.active_waitlist_count}, ${cursorRow.id})
        ORDER BY active_waitlist_count DESC, id DESC
        LIMIT ${PAGE_SIZE + 1}
      `;
    } else {
      snapshots = await sql<typeof snapshots>`
        SELECT id, product_external_id, variant_external_id, item_display_name,
               active_waitlist_count, total_signups, total_notified, total_conversions,
               last_restock_at
        FROM dashboard_snapshots
        ORDER BY active_waitlist_count DESC, id DESC
        LIMIT ${PAGE_SIZE + 1}
      `;
    }

    const hasMore = snapshots.length > PAGE_SIZE;
    const page = snapshots.slice(0, PAGE_SIZE);
    const nextCursor = hasMore && page.length > 0
      ? encodeCursor(page[page.length - 1]!.id)
      : null;

    // Total count
    const [countRow] = await sql<{ count: string }[]>`
      SELECT COUNT(*) AS count FROM dashboard_snapshots
    `;
    const totalCount = parseInt(countRow?.count ?? "0", 10);

    // Overall metrics
    const [metricsRow] = await sql<{
      total_signups: string;
      total_notified: string;
      total_conversions: string;
    }[]>`
      SELECT
        COALESCE(SUM(total_signups), 0) AS total_signups,
        COALESCE(SUM(total_notified), 0) AS total_notified,
        COALESCE(SUM(total_conversions), 0) AS total_conversions
      FROM dashboard_snapshots
    `;

    const totalSignups = parseInt(metricsRow?.total_signups ?? "0", 10);
    const totalNotified = parseInt(metricsRow?.total_notified ?? "0", 10);
    const totalConversions = parseInt(metricsRow?.total_conversions ?? "0", 10);

    const overallMetrics: OverallMetrics = {
      total_signups: totalSignups,
      total_notified: totalNotified,
      total_conversions: totalConversions,
      conversion_rate: totalNotified > 0 ? Math.round((totalConversions / totalNotified) * 10000) / 100 : 0,
    };

    const items: DashboardItem[] = page.map((s) => ({
      product_external_id: String(s.product_external_id),
      variant_external_id: s.variant_external_id !== null ? String(s.variant_external_id) : null,
      item_display_name: s.item_display_name,
      active_waitlist_count: s.active_waitlist_count,
      total_signups: s.total_signups,
      total_notified: s.total_notified,
      total_conversions: s.total_conversions,
      conversion_rate: s.total_notified > 0
        ? Math.round((s.total_conversions / s.total_notified) * 10000) / 100
        : 0,
      last_restock_at: s.last_restock_at ? s.last_restock_at.toISOString() : null,
    }));

    const response: AdminDashboardResponse = {
      items,
      next_cursor: nextCursor,
      total_count: totalCount,
      overall_metrics: overallMetrics,
    };

    res.json(response);
  } catch (err) {
    console.error({ requestId: req.platform!.requestId, err: String(err) }, "dashboard failed");
    res.status(500).json({ error: "internal error" });
  }
});

// ─── GET /admin/subscribers ────────────────────────────────────────────────────

adminRouter.get("/admin/subscribers", async (req: Request, res: Response): Promise<void> => {
  const productIdRaw = typeof req.query.product_id === "string" ? req.query.product_id : null;
  const variantIdRaw = typeof req.query.variant_id === "string" ? req.query.variant_id : null;
  const cursorRaw = typeof req.query.cursor === "string" ? req.query.cursor : null;

  if (!productIdRaw) {
    res.status(400).json({ error: "product_id is required" });
    return;
  }

  if (!/^\d+$/.test(productIdRaw)) {
    res.status(400).json({ error: "product_id must be a numeric string" });
    return;
  }

  if (variantIdRaw !== null && !/^\d+$/.test(variantIdRaw)) {
    res.status(400).json({ error: "variant_id must be a numeric string" });
    return;
  }

  try {
    const productId = BigInt(productIdRaw);
    const variantId = variantIdRaw !== null ? BigInt(variantIdRaw) : null;

    let cursorDate: Date | null = null;
    let cursorId: string | null = null;
    if (cursorRaw) {
      const decoded = decodeCursor(cursorRaw);
      const parts = decoded.split("|");
      if (parts.length === 2 && parts[0] && parts[1]) {
        cursorDate = new Date(parts[0]);
        cursorId = parts[1];
      }
    }

    type EntryRow = {
      id: string;
      shopper_email: string;
      product_external_id: bigint;
      variant_external_id: bigint | null;
      item_display_name: string;
      signup_level: string;
      status: string;
      signed_up_at: Date;
      notified_at: Date | null;
      notification_batch_id: string | null;
    };

    let entries: EntryRow[];

    if (variantId !== null) {
      if (cursorDate && cursorId) {
        entries = await sql<EntryRow[]>`
          SELECT id, shopper_email, product_external_id, variant_external_id,
                 item_display_name, signup_level, status, signed_up_at, notified_at, notification_batch_id
          FROM waitlist_entries
          WHERE product_external_id = ${productId}
          AND variant_external_id = ${variantId}
          AND (signed_up_at, id) > (${cursorDate}, ${cursorId})
          ORDER BY signed_up_at ASC, id ASC
          LIMIT ${PAGE_SIZE + 1}
        `;
      } else {
        entries = await sql<EntryRow[]>`
          SELECT id, shopper_email, product_external_id, variant_external_id,
                 item_display_name, signup_level, status, signed_up_at, notified_at, notification_batch_id
          FROM waitlist_entries
          WHERE product_external_id = ${productId}
          AND variant_external_id = ${variantId}
          ORDER BY signed_up_at ASC, id ASC
          LIMIT ${PAGE_SIZE + 1}
        `;
      }
    } else {
      if (cursorDate && cursorId) {
        entries = await sql<EntryRow[]>`
          SELECT id, shopper_email, product_external_id, variant_external_id,
                 item_display_name, signup_level, status, signed_up_at, notified_at, notification_batch_id
          FROM waitlist_entries
          WHERE product_external_id = ${productId}
          AND variant_external_id IS NULL
          AND (signed_up_at, id) > (${cursorDate}, ${cursorId})
          ORDER BY signed_up_at ASC, id ASC
          LIMIT ${PAGE_SIZE + 1}
        `;
      } else {
        entries = await sql<EntryRow[]>`
          SELECT id, shopper_email, product_external_id, variant_external_id,
                 item_display_name, signup_level, status, signed_up_at, notified_at, notification_batch_id
          FROM waitlist_entries
          WHERE product_external_id = ${productId}
          AND variant_external_id IS NULL
          ORDER BY signed_up_at ASC, id ASC
          LIMIT ${PAGE_SIZE + 1}
        `;
      }
    }

    const hasMore = entries.length > PAGE_SIZE;
    const page = entries.slice(0, PAGE_SIZE);
    const lastEntry = page[page.length - 1];
    const nextCursor = hasMore && lastEntry
      ? encodeCursor(`${lastEntry.signed_up_at.toISOString()}|${lastEntry.id}`)
      : null;

    // Total count
    let totalCountRow: { count: string }[];
    if (variantId !== null) {
      totalCountRow = await sql<{ count: string }[]>`
        SELECT COUNT(*) AS count FROM waitlist_entries
        WHERE product_external_id = ${productId}
        AND variant_external_id = ${variantId}
      `;
    } else {
      totalCountRow = await sql<{ count: string }[]>`
        SELECT COUNT(*) AS count FROM waitlist_entries
        WHERE product_external_id = ${productId}
        AND variant_external_id IS NULL
      `;
    }
    const totalCount = parseInt(totalCountRow[0]?.count ?? "0", 10);

    const subscribers: SubscriberItem[] = page.map((e) => ({
      id: e.id,
      shopper_email: e.shopper_email,
      product_external_id: String(e.product_external_id),
      variant_external_id: e.variant_external_id !== null ? String(e.variant_external_id) : null,
      item_display_name: e.item_display_name,
      signup_level: e.signup_level as import("../types/contracts.js").SignupLevel,
      status: e.status as import("../types/contracts.js").WaitlistStatus,
      signed_up_at: e.signed_up_at.toISOString(),
      notified_at: e.notified_at ? e.notified_at.toISOString() : null,
      notification_batch_id: e.notification_batch_id,
    }));

    const response: AdminSubscribersResponse = {
      subscribers,
      next_cursor: nextCursor,
      total_count: totalCount,
    };

    res.json(response);
  } catch (err) {
    console.error({ requestId: req.platform!.requestId, err: String(err) }, "subscribers list failed");
    res.status(500).json({ error: "internal error" });
  }
});

